const DEMOS={charizardex:{name:'Charizard ex',type:'Feu',energy:'🔥',hp:'250 PV',attack:'Wing Attack · 30 / Crimson Storm · 300',rarity:'À confirmer',set:'À confirmer',year:'À confirmer',color:'#e85d45',symbol:'🔥'},rayquazaex:{name:'Rayquaza ex',type:'Dragon',energy:'✦',hp:'230 PV',attack:'Dragon Ascent · 300',rarity:'À confirmer',set:'À confirmer',year:'À confirmer',color:'#7eaf77',symbol:'✦'},pikachu:{name:'Pikachu',type:'Électrique',energy:'⚡',hp:'60 PV',attack:'Éclair · 30',rarity:'Commune',set:'Écarlate & Violet · 025/198',year:'2023',color:'#f4c542',symbol:'⚡'},dracaufeu:{name:'Dracaufeu',type:'Feu',energy:'🔥',hp:'180 PV',attack:'Fournaise · 180',rarity:'Ultra Rare',set:'Évolutions · 011/108',year:'2016',color:'#e85d45',symbol:'🔥'},evoli:{name:'Évoli',type:'Incolore',energy:'✦',hp:'50 PV',attack:'Charge · 20',rarity:'Illustration Rare',set:'Destinées de Paldea · 188/193',year:'2023',color:'#c99268',symbol:'✦'},mewtwo:{name:'Mewtwo',type:'Psy',energy:'◈',hp:'130 PV',attack:'Psyko · 90',rarity:'Rare Holo',set:'151 · 150/165',year:'2023',color:'#9d85d3',symbol:'◈'}};
const KEY='carddex-library-v1';let mode='owner',pending=null,selectedFiles=[];
const $=s=>document.querySelector(s);const library=()=>JSON.parse(localStorage.getItem(KEY)||'[]');const save=x=>localStorage.setItem(KEY,JSON.stringify(x));
function toast(t){const e=$('#toast');e.textContent=t;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2600)}
function render(){let cards=mode==='owner'?library():(window.guestCards||[]);const q=$('#searchInput').value.toLowerCase();const sort=$('#sortSelect').value;cards=cards.filter(c=>c.name.toLowerCase().includes(q));cards=[...cards].sort((a,b)=>sort==='name'?a.name.localeCompare(b.name):sort==='type'?a.type.localeCompare(b.type):(b.added||0)-(a.added||0));$('#cardCount').textContent=mode==='owner'?library().length:'—';$('#typeCount').textContent=mode==='owner'?new Set(library().map(c=>c.type)).size:'—';$('#rareCount').textContent=mode==='owner'?library().filter(c=>/rare|ultra|illustration/i.test(c.rarity)).length:'—';$('#valueCount').textContent='—';$('#emptyState').classList.toggle('visible',cards.length===0);$('#library').innerHTML=cards.map((c,i)=>`<article class="card-tile" data-index="${i}"><div class="card-image" style="background:${c.color}"><span class="tag">${c.rarity}</span><span class="card-symbol">${c.symbol}</span></div><div class="tile-meta"><h3>${c.name}</h3><p>${c.type} · ${c.hp}</p></div></article>`).join('');document.querySelectorAll('.card-tile').forEach((el,i)=>el.onclick=()=>showDetail(cards[i]));$('#modeLabel').textContent=mode==='owner'?'Ma collection':'Mode invité';$('#modePill .mode-dot').style.background=mode==='owner'?'var(--red)':'var(--blue)'}
function setMode(next){mode=next;$('#modalMode').textContent=mode==='owner'?'collection':'invité';$('#privacyText').textContent=mode==='owner'?'les cartes confirmées seront enregistrées localement':'rien ne sera enregistré';render()}
function openScan(){selectedFiles=[];pending=null;$('#photoInput').value='';$('#previewArea').hidden=true;$('#previewArea').innerHTML='';$('#analyzeBtn').disabled=true;$('#scanModal').hidden=false}
function closeScan(){$('#scanModal').hidden=true}
function useDemo(key){pending=structuredClone(DEMOS[key]);selectedFiles=[];$('#analyzeBtn').disabled=false;$('#previewArea').hidden=false;$('#previewArea').innerHTML=`<div class="demo-preview" style="background:${pending.color};width:58px;height:74px;border-radius:6px;display:grid;place-items:center;font-size:24px">${pending.symbol}</div>`;toast('Carte de démonstration prête à vérifier')}
function onFiles(files){selectedFiles=[...files];if(!files.length)return;$('#previewArea').hidden=false;$('#previewArea').innerHTML=selectedFiles.slice(0,6).map(f=>`<img alt="Aperçu de ${f.name}" src="${URL.createObjectURL(f)}">`).join('');$('#analyzeBtn').disabled=false;pending=null}
function analyze(){if(!pending){pending={name:'Carte non reconnue',type:'—',energy:'?',hp:'—',attack:'À confirmer',rarity:'Non déterminée',set:'Non déterminée',year:'Non déterminée',color:'#d8d2c5',symbol:'?',source:'Photo non identifiée',unrecognized:true};}pending.added=Date.now();showDetail(pending,true)}
function showDetail(c,confirmable=false){const caution=c.unrecognized?'ⓘ La photo n’a pas permis d’identifier cette carte de façon fiable. Choisissez son nom manuellement ou réessayez avec une carte seule, bien cadrée et lisible.':"ⓘ Prix, état et authenticité : aucune API ni expertise n'est connectée dans ce MVP. Vérifiez ces informations auprès d'une source spécialisée avant toute décision.";$('#detailContent').innerHTML=`<div class="detail-top"><div class="detail-card" style="background:${c.color}">${c.symbol}</div><div class="detail-content"><p class="eyebrow">Résultat ${confirmable?'à confirmer':'de la bibliothèque'}</p><h2>${c.name}</h2><div class="subtitle">${c.type} · ${c.hp}</div></div></div><div class="info-grid"><div><small>Attaque</small><strong>${c.attack}</strong></div><div><small>Rareté</small><strong>${c.rarity}</strong></div><div><small>Édition / numéro</small><strong>${c.set}</strong></div><div><small>Année</small><strong>${c.year}</strong></div><div><small>Prix en euros</small><strong>Non disponible</strong></div><div><small>État estimé</small><strong>À évaluer</strong></div></div><div class="caution">${caution}</div>${confirmable&&!c.unrecognized?`<button class="primary-btn full" id="confirmCard">${mode==='owner'?'Ajouter à ma bibliothèque':'Fermer sans enregistrer'}</button>`:''}${c.unrecognized?'<button class="primary-btn full" id="manualCard">Choisir le nom manuellement</button>':''}`;$('#detailModal').hidden=false;if(confirmable&&!c.unrecognized)$('#confirmCard').onclick=()=>{if(mode==='owner'){const cards=library();cards.push({...pending,source:'Choix manuel'});save(cards);toast('Carte ajoutée à votre bibliothèque')}else toast('Mode invité : rien n’a été enregistré');$('#detailModal').hidden=true;closeScan();render()};if(c.unrecognized)$('#manualCard').onclick=()=>{$('#detailModal').hidden=true;toast('Choisissez une carte dans la fenêtre de scan')}}
$('#scanHero').onclick=openScan;$('#scanNav').onclick=openScan;$('#emptyScan').onclick=openScan;$('#guestHero').onclick=()=>{setMode('guest');openScan()};$('#modeToggle').onclick=()=>setMode(mode==='owner'?'guest':'owner');$('#closeScan').onclick=closeScan;$('#closeDetail').onclick=()=>$('#detailModal').hidden=true;$('#photoInput').onchange=e=>onFiles(e.target.files);$('#analyzeBtn').onclick=analyze;document.querySelectorAll('[data-demo]').forEach(b=>b.onclick=()=>useDemo(b.dataset.demo));$('#searchInput').oninput=render;$('#sortSelect').onchange=render;$('#showAll').onclick=()=>{$('#searchInput').value='';render()};$('#aboutNav').onclick=()=>toast('CardDex est un MVP local-first : aucune photo ne quitte votre navigateur.');window.onclick=e=>{if(e.target.classList.contains('modal-backdrop'))e.target.hidden=true};if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});render();
